import sys

fa = {}
name = None
for line in open(sys.argv[1]):
    if line.startswith(">"):
        name = line[1:].strip().split()[0]
        fa[name] = []
    else:
        fa[name].append(line.strip())

contig = fa["chrM"]
with open(sys.argv[2], "w") as out:
    out.write(str(len(contig)) + "\n")
